import {normalizeEndpoint,discoverModels,apiRequest,connectionError,localBridgeAvailable} from './ai-client.js?v=2.1.0';
import {DIM,SEGMENTS,DATASETS,MODES,TECHS,EVENTS,BENCHMARKS,ROLES,INVESTORS,GLOSSARY} from './data.js?v=2.1.0';
import * as E from './engine.js?v=2.1.0';
import * as C from './campaign.js?v=2.1.0';
import {RIVALS,BRANDS,availableRivals,indexScore} from './rivals.js?v=2.1.0';
import {createImmersiveViews} from './immersive.js?v=2.1.0';
const $=s=>document.querySelector(s);
const KEY='frontier-lab-save-v1';
let state;try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');state=E.validateSave(raw)?raw:E.initialState();}catch{state=E.initialState();}
C.ensureCampaign(state);
let arenaOwn=state.models.at(-1).id,arenaRival='',arenaTab='compare',rankGroup='overall',duelTimer=null,audioContext=null,ambientNodes=[];
let view='overview',config=E.defaultConfig(state),dataFilter='all',socialFilter='all',researchTab='builder',showFuture=false,autoTimer=null,aiKey='',aiBusy=false;
let aiModels=[],aiModelStatus='填写地址和密钥后会自动读取模型，也可以手动刷新。',aiModelsBusy=false,aiDiscoveryId=0,aiDiscoveryController=null,aiDiscoveryTimer=null;
let aiConfig;try{aiConfig=JSON.parse(localStorage.getItem('frontier-ai-config')||'{}');}catch{aiConfig={};}
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const safeUrl=u=>{try{const url=new URL(u);return ['https:','http:'].includes(url.protocol)?url.href:'#';}catch{return '#';}};
const n=(v,d=0)=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const compact=v=>Math.abs(v)>=10000?(v/10000).toFixed(1)+'万':n(v);
const money=(v,d=1)=>'¥'+n(v,d);
const date=()=>E.dateOf(state);
const titles={overview:'公司总部',research:'研发实验室',arena:'模型竞技场',data:'材料与基座',products:'产品发布',market:'用户与增长',community:'社区广场',opportunities:'合作机会',finance:'公司经营',history:'行业时间线'};
const paths={arena:'M8 3h8v6a4 4 0 0 1-8 0V3 M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 13v6 M8 21h8 M9 19h6',opportunities:'M4 6h16v15H4z M8 3h8v6H8z M8 13h8 M8 17h5',overview:'M3 10h7V3H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',research:'M9 3h6 M10 3v6l-6 10a1.3 1.3 0 0 0 1.2 2h13.6A1.3 1.3 0 0 0 20 19L14 9V3 M8 14h8',data:'M4 6c0-4 16-4 16 0s-16 4-16 0v12c0 4 16 4 16 0V6 M4 12c0 4 16 4 16 0',products:'M12 3l8 5v9l-8 5-8-5V8l8-5z M4 8l8 5 8-5 M12 13v9',market:'M4 19V5 M4 19h17 M8 15l4-5 4 2 5-8',community:'M20 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 16-5z M8 10h8 M8 14h5',finance:'M3 7h18v13H3z M3 7l3-4h12l3 4 M3 11h18 M8 15h2 M16 15h2',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v6l4 2',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',chevron:'M8 10l4 4 4-4',close:'M6 6l12 12 M18 6L6 18',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',wallet:'M3 6h17v15H3z M3 6V3h15v3 M15 11h6v6h-6z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M18 8a3 3 0 0 1 0 6 M19 17a3 3 0 0 1 3 3',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c-5 5-5 13 0 18 5-5 5-13 0-18',check:'M5 12l4 4L20 5',alert:'M12 3L2 21h20L12 3z M12 9v5 M12 17v1',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 4l3 1 3-3h4l3 3 3-1 2 4-2 3 2 3-2 4-3-1-3 3h-4l-3-3-3 1-2-4 2-3-2-3z',heart:'M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1c-5 5 8 15 8 15S25 10 20 5z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v6l4 2',code:'M8 6l-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',cpu:'M6 6h12v12H6z M9 9h6v6H9z M9 2v4 M15 2v4 M9 18v4 M15 18v4 M2 9h4 M2 15h4 M18 9h4 M18 15h4',play:'M7 4l14 8-14 8z',pause:'M7 4v16 M17 4v16',copy:'M8 8h13v13H8z M16 8V3H3v13h5',flag:'M5 22V3h14l-3 5 3 5H5'};
function icon(id,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.spark}"/></svg>`;}
const btn=(text,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const ui={icon,btn,chip,esc,n,money,compact,caps,empty};
const I=createImmersiveViews(ui);
function toast(text,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=text;$('#toasts').append(el);setTimeout(()=>el.remove(),5200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('当前浏览器无法保存进度，请在设置中导出存档。',true);}}
function act(result,success){if(result?.error){toast(result.error,true);return false;}save();render();if(success)toast(success);return true;}
function head(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">FRONTIER LAB / ${view.toUpperCase()}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function avatar(gid){const g=SEGMENTS.find(g=>g.id===gid)||SEGMENTS[2];return `<div class="avatar" style="--avatar-color:${g.color}">${g.icon}</div>`;}
function chip(text,cls=''){return `<span class="chip ${cls}">${text}</span>`;}
function sparkline(values,color='var(--orange)'){if(values.length<2)values=[values[0]||0,values[0]||0];const min=Math.min(...values),max=Math.max(...values),range=max-min||1;return `<svg class="stat-spark" viewBox="0 0 70 20"><polyline points="${values.map((v,i)=>`${i*70/(values.length-1)},${18-(v-min)/range*15}`).join(' ')}" fill="none" stroke="${color}" stroke-width="1.3"/></svg>`;}
function stat(label,value,unit,foot,ico,values=[],positive=false){return `<div class="stat"><div class="stat-top">${label}${icon(ico)}</div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-foot"><span class="${positive?'positive':''}">${foot}</span>${sparkline(values)}</div></div>`;}
function caps(scores){return `<div class="cap-list">${DIM.map((d,i)=>`<div class="cap-row" style="--c:${d.color}"><span>${d.short}</span><div><i style="width:${E.clamp(scores[i],0,100)}%"></i></div><span>${n(scores[i])}</span></div>`).join('')}</div>`;}
function panelHeader(title,action='',number=''){return `<div class="panel-head"><h2>${title}${number?`<span class="number">${number}</span>`:''}</h2>${action}</div>`;}
function chart(data,keys=['revenue','expense'],colors=['#e9a576','#a5c3a7']){const rows=data.length?data.slice(-20):Array.from({length:8},(_,i)=>({revenue:0,expense:E.fixedBurn(state),cash:state.cash,users:0}));const all=rows.flatMap(r=>keys.map(k=>r[k]||0));const max=Math.max(1,...all)*1.2,min=Math.min(0,...all);const x=i=>38+i*640/Math.max(1,rows.length-1),y=v=>132-(v-min)/(max-min)*110;let grid='';for(let i=0;i<4;i++){const v=min+(max-min)*i/3;grid+=`<line x1="38" x2="690" y1="${y(v)}" y2="${y(v)}" stroke="#33402f" stroke-width=".7" stroke-dasharray="3 5"/><text x="27" y="${y(v)+3}" text-anchor="end" fill="#75896c" font-size="9" font-family="monospace">${v>=1000?compact(v):n(v,Math.abs(v)<10?1:0)}</text>`;}const lines=keys.map((key,j)=>{const points=rows.map((r,i)=>`${x(i)},${y(r[key]||0)}`).join(' ');return `${j===0?`<defs><linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${colors[j]}" stop-opacity=".14"/><stop offset="100%" stop-color="${colors[j]}" stop-opacity="0"/></linearGradient></defs><polygon points="${x(0)},${y(min)} ${points} ${x(rows.length-1)},${y(min)}" fill="url(#chartGradient)"/>`:''}<polyline points="${points}" stroke="${colors[j]}" stroke-width="2.1" stroke-linejoin="round" fill="none"/><circle cx="${x(rows.length-1)}" cy="${y(rows.at(-1)[key]||0)}" r="3" fill="${colors[j]}"/>`;}).join('');return `<div class="chart-wrap"><svg class="chart" viewBox="0 0 704 148" preserveAspectRatio="none" role="img" aria-label="最近二十周的经营变化">${grid}${lines}</svg><div class="chart-labels"><span>${data.length?rows[0].date:'2022.01.03'}</span><span>经营周 / WEEK ${state.week.toString().padStart(2,'0')}</span><span>${date()}</span></div></div>`;}
function renderSidebar(){const pending=state.projects.filter(p=>p.status==='running').length;const unread=state.campaign.events.filter(e=>e.status==='pending').length;$('#sidebar').innerHTML=`<div class="brand" title="前沿实验室 / Frontier Lab"><div class="brand-mark"><i></i><i></i><i></i><i></i></div></div><nav class="nav">${Object.entries(titles).map(([id,title])=>`<button class="nav-btn ${view===id?'active':''}" data-action="nav" data-view="${id}" title="${title}">${icon(id)}<span>${title}</span>${id==='research'&&pending?`<span class="count">${pending}</span>`:''}${id==='opportunities'&&state.campaign.contracts.some(t=>t.status==='complete')?'<span class="count">!</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-tools"><button data-action="glossary">入门手册</button><button data-action="settings">设置 / 存档</button></div></div>`;}
function renderTop(){const unread=state.campaign.events.filter(e=>e.status==='pending').length;$('#topbar').innerHTML=`<div class="breadcrumb"><span class="prefix">FRONTIER LAB</span><span class="slash">/</span><b>${titles[view]}</b></div><div class="top-context"><div class="hud-company">${esc(state.company)}<small>FOUNDER'S EDITION / ${C.chapter(state).number}</small></div><div class="hud-resources"><span>${icon('wallet')}${money(state.cash,1)}万</span><span>${icon('users')}${compact(E.totalUsers(state))}</span></div><button class="hud-inbox" data-action="inbox" title="桌上的来信" aria-label="打开来信">${icon('community')}${unread?`<i>${unread}</i>`:''}</button><div class="date-control"><div class="game-date">${date().replaceAll('-','.')}<small>第 ${state.week+1} 周 · ${autoTimer?'正在推进':'时间暂停'}</small></div><div class="advance-group">${btn('推进一周 '+icon('arrow'),'advance','primary',state.cash<0?'disabled':'')}${btn(icon('chevron'),'advanceMenu','primary advance-more','aria-label="更多时间控制"')}</div></div></div>`;}
function advisor(){const failed=state.projects.find(p=>p.status==='failed');if(state.cash<0)return {text:'现金不足。你仍可签署已有投资报价，或使用应急融资继续经营。也可以先调整免费补贴、营销和算力。',action:'finance',label:'查看融资方案'};if(failed)return {text:'有一个训练项目中断了。查看异常原因和已保存进度，可以追加检查后恢复，也可以保留已有模型，转向其他项目。',action:'research',label:'检查训练项目'};if(!state.models.some(m=>m.published))return {text:'你可以改进 Seed-0 原型，或从头设计模型。代码和角色对话可以一起做；先获取合适的材料，再决定训练配比。',action:'research',label:'进入模型实验台'};if(state.last.capacity<.65)return {text:'用户增长开始挤占服务容量。可以增加算力、降低免费额度，或尝试把旗舰蒸馏为更轻的版本。',action:'market',label:'检查服务与补贴'};if(E.runway(state)<12)return {text:'按最近一周收支，现金可支撑的时间已少于 12 周。融资需要时间，建议同时检查支出和用户付费情况。',action:'finance',label:'查看现金与融资'};return {text:'继续观察不同群体的使用反馈。你可以迭代通用模型，也可以从同一基座发展专业版，并行尝试新的技术路线。',action:'community',label:'看看社区在说什么'};}
function projectRow(p){const status=p.status==='running'?'训练中':p.status==='paused'?'已暂停':p.status==='failed'?'训练中断':'已完成';const cls=p.status==='failed'?'red':p.status==='done'?'':'orange';return `<div class="project-row"><div class="project-top"><div class="project-title">${esc(p.name)}<small>${p.type!=='train'?(p.type==='collection'?'DATA COLLECTION':p.type==='integration'?'BASE INTEGRATION':'ENGINEERING'):(p.estimate.arch==='moe'?'MoE':'Dense')+' / '+n(p.estimate.params,2)+'B'}</small></div>${chip(p.type==='tech'&&p.status==='running'?'研究中':status,cls)}</div><div class="progress ${p.status==='done'?'green':''}"><i style="width:${p.progress*100}%"></i></div><div class="project-info"><span>${p.type==='train'?`已保存 ${n(p.checkpoint*100)}% · ${p.gpus} 张 GPU`:'工程成熟度积累'}</span><span>${n(p.progress*100)}%</span></div>${p.status==='failed'?`<div class="form-note">${esc(p.reason)}</div><div class="project-actions">${btn('检查并恢复','resume','small soft',`data-id="${p.id}"`)}${btn('查看设置','cloneProject','small ghost',`data-id="${p.id}"`)}</div>`:p.status==='running'?`<div class="project-actions">${btn('暂停项目','pauseProject','small ghost',`data-id="${p.id}"`)}</div>`:p.status==='paused'?`<div class="project-actions">${btn('继续项目','unpauseProject','small soft',`data-id="${p.id}"`)}</div>`:p.status==='done'&&['train','integration','collection'].includes(p.type)?`<div class="project-actions">${p.type==='collection'?btn('查看入库材料','nav','small soft','data-view="data"'):p.pilot?btn('继续此方案','cloneProject','small soft',`data-id="${p.id}"`):btn('评测与发布 '+icon('arrow'),'nav','small soft','data-view="products"')}</div>`:''}</div>`;}
function heroArt(){let lines='',nodes='';const coords=[[45,65],[90,30],[90,100],[145,55],[145,130],[205,85],[205,160],[90,175],[35,130]];for(let i=0;i<coords.length;i++){for(let j=i+1;j<coords.length;j++){if((i+j)%3===0||j===i+1)lines+=`<line x1="${coords[i][0]}" y1="${coords[i][1]}" x2="${coords[j][0]}" y2="${coords[j][1]}" stroke="#8ca46a" stroke-width=".6" opacity=".5"/>`;}nodes+=`<circle cx="${coords[i][0]}" cy="${coords[i][1]}" r="${i%3===0?5:3}" fill="${i===3?'#e9a576':'#9cb577'}"/>`;}return `<svg class="hero-art" viewBox="0 0 245 200"><g fill="none" stroke="#4b603a" stroke-width=".6"><ellipse cx="126" cy="104" rx="105" ry="75" transform="rotate(-30 126 104)"/><ellipse cx="126" cy="104" rx="105" ry="75" transform="rotate(30 126 104)"/><ellipse cx="126" cy="104" rx="68" ry="90"/></g>${lines}${nodes}<circle cx="145" cy="55" r="13" fill="none" stroke="#e9a576" opacity=".4"/></svg>`;}
function overview(){return I.hq(state);}
function arena(){return I.arena(state,{own:arenaOwn,rival:arenaRival,tab:arenaTab,group:rankGroup});}
function opportunities(){return I.opportunities(state);}
function field(label,html,help='',full=false){html=html.replace(/<(input|select|textarea)(?=\s)/,(tag,kind,offset)=>kind==='input'&&html.slice(offset,html.indexOf('>',offset)).includes('type="checkbox"')?tag:tag+' aria-label="'+esc(label)+'"');return `<div class="field ${full?'full':''}"><label>${label}</label>${html}${help?`<small>${help}</small>`:''}</div>`;}
function option(v,text,selected,disabled=false){return `<option value="${esc(v)}" ${selected?'selected':''} ${disabled?'disabled':''}>${esc(text)}</option>`;}
function inputConf(key,type='number',attrs=''){return `<input type="${type}" data-config="${key}" value="${esc(config[key])}" ${attrs}>`;}
function research(){const tabs=`<div class="tabs">${[['builder','模型实验台'],['projects','项目与实验'],['technology','工程研究'],['library','模型库']].map(([id,text])=>`<button class="tab ${researchTab===id?'active':''}" data-action="researchTab" data-tab="${id}">${text}${id==='projects'?` · ${state.projects.filter(p=>p.status==='running').length}`:''}</button>`).join('')}</div>`;let body='';if(researchTab==='builder'){const e=E.estimate(state,config),inherit=!['scratch','distill'].includes(config.mode);const mode=MODES[config.mode];body=`<div class="preset-row"><button class="preset" data-action="preset" data-preset="balanced">${icon('spark')}通用起步方案</button><button class="preset" data-action="preset" data-preset="both">${icon('code')}代码与创作，两手抓</button><button class="preset" data-action="preset" data-preset="scratch">${icon('cpu')}从头设计基座</button><button class="preset" data-action="preset" data-preset="distill">${icon('copy')}蒸馏轻量版本</button></div><div class="grid builder-grid"><div class="panel"><div class="builder-section"><div class="builder-title"><span class="step-num">01</span>项目与训练方式 ${helpButton()}</div><div class="form-grid">${field('项目名称',inputConf('name','text','maxlength="45"'),'',true)}${field('这轮怎么训练？',`<select data-config="mode">${Object.entries(MODES).map(([id,m])=>option(id,m.name+(m.date&&!E.unlocked(state,m.date)?' · '+m.date+' 公开':''),config.mode===id,!E.unlocked(state,m.date))).join('')}</select>`)}${field(inherit?'基础模型':'学生 / 初始模型',inherit?`<select data-config="base">${state.models.map(m=>option(m.id,m.name,config.base===m.id)).join('')}</select>`:`<input value="${config.mode==='distill'?'按下面配置创建学生模型':'随机初始化新模型'}" disabled>`)}${config.mode==='distill'?field('教师模型',`<select data-config="teacher">${option('licensed','外部合作教师（游戏模拟授权）',config.teacher==='licensed')}${state.models.map(m=>option(m.id,m.name,config.teacher===m.id)).join('')}</select>`,'外部教师按当前时代模拟能力；自有模型可直接提供训练信号。',true):''}</div><div class="form-note">${mode.simple}。${mode.help}</div></div><div class="builder-section"><div class="builder-title"><span class="step-num">02</span>模型结构 ${inherit?chip('沿用基础模型结构'):''}</div><div class="form-grid">${field('计算结构',`<select data-config="arch" ${inherit?'disabled':''}>${option('dense','Dense · 稠密结构',e.arch==='dense')}${option('moe','MoE · 专家混合',e.arch==='moe')}</select>`,'结构影响容量、成本与训练稳定性。')}${field('模型总参数 · B',`<input type="number" data-config="params" value="${inherit?e.params:config.params}" min="0.1" max="500" step="0.1" ${inherit?'disabled':''}>`,'1B 表示十亿参数，规模需要匹配训练量。')}${field('注意力方案',`<select data-config="attention" ${inherit?'disabled':''}>${option('mha','MHA · 标准多头',e.attention==='mha')}${option('mqa','MQA · 多查询',e.attention==='mqa')}${option('gqa','GQA · '+(state.tech.gqa?'已掌握':'需要工程研究'),e.attention==='gqa',!state.tech.gqa)}${option('mla','MLA · '+(state.tech.mla?'已掌握':'需要工程研究'),e.attention==='mla',!state.tech.mla)}</select>`)}${field('上下文长度',`<select data-config="context" ${inherit?'disabled':''}>${[1024,2048,4096,8192,32768,131072].map(x=>option(x,n(x)+' tokens',e.context===x)).join('')}</select>`,'长上下文需要相应材料与算力支持。')}${e.arch==='moe'?field('专家数量',`<select data-config="experts" ${inherit?'disabled':''}>${[4,8,16,32].map(x=>option(x,x+' 个专家',config.experts===x)).join('')}</select>`)+field('每次激活专家',`<select data-config="topK" ${inherit?'disabled':''}>${[1,2,4].map(x=>option(x,x+' 个专家',config.topK===x)).join('')}</select>`):''}</div></div><div class="builder-section"><div class="builder-title"><span class="step-num">03</span>这轮用什么材料？<button class="text-btn" style="margin-left:auto" data-action="nav" data-view="data">获取更多材料 ↗</button></div><div id="mix-visual">${mixVisual()}</div>${E.datasets(state).filter(d=>state.inventory[d.id]).map((d,i)=>`<div class="mix-row"><div class="mix-label">${d.name}<small>质量 ${n(E.dataInfo(state,d.id).quality)} · ${n(E.dataInfo(state,d.id).tokens,1)}B tokens</small></div><input type="range" min="0" max="100" step="1" data-weight="${d.id}" value="${config.weights[d.id]||0}" aria-label="${d.name}训练权重"><div class="mix-value" id="weight-${d.id}">${weightPercent(d.id)}%</div></div>`).join('')}<div class="help">比例按相对权重自动计算。材料可以用于多个项目，重复过多可能影响泛化。</div></div><div class="builder-section"><div class="builder-title"><span class="step-num">04</span>训练投入与保障</div><div class="form-grid">${field('本轮训练量 · B tokens',inputConf('volume','number','min="0.05" max="300" step="0.1"'),'训练量与材料配比共同决定实际读取内容。')}${field('申请使用 GPU',inputConf('gpus','number','min="1" max="512" step="1"'),'并行项目共享租用算力，超额时按份额分配。')}${field('训练节奏',`<select data-config="pace">${option('careful','稳健 · 更多验证时间',config.pace==='careful')}${option('balanced','平衡 · 标准推进',config.pace==='balanced')}${option('aggressive','激进 · 更快但风险更高',config.pace==='aggressive')}</select>`)}${field('进度保障',`<label class="check-row" style="margin-top:8px"><input type="checkbox" data-config="checkpoint" ${config.checkpoint?'checked':''}>自动保存检查点</label>`,'中断后可以恢复已保存部分，重试仍有成本。')}</div></div></div><aside class="panel builder-side"><div class="panel-head"><h2>本轮投入预估</h2>${chip('模拟估计')}</div><div class="estimate-pad" id="estimate">${estimateHtml()}</div></aside></div>`;}else if(researchTab==='projects'){body=`<div class="grid two-col"><div class="stack"><div class="panel">${panelHeader('研发项目','',String(state.projects.length).padStart(2,'0'))}${state.projects.length?[...state.projects].reverse().map(projectRow).join(''):empty('还没有研发项目','设计第一轮实验，或同时开启几条研究路线。','创建项目','builder')}</div></div><div class="panel">${panelHeader('小实验记录')}${state.experiments.length?state.experiments.slice().reverse().map(e=>`<div class="project-row"><div class="flex spaced"><span class="project-title">${esc(e.name)}</span>${chip('已验证')}</div><p class="help">${esc(e.report)}</p><span class="backup-time">${e.date}</span></div>`).join(''):empty('让实验减少未知','小实验消耗少量预算，帮助检查方案；你也可以直接正式训练。')}</div></div>`;}else if(researchTab==='technology'){body=`<div class="notice">${icon('book')}<p>技术公开后即可投入工程研究。MoE 在开局前已存在，你可以直接尝试，也可以先提高团队熟练度。</p></div><div class="grid tech-grid">${TECHS.map(t=>{const locked=!E.unlocked(state,t.date),running=state.projects.find(p=>p.tech===t.id&&p.status==='running');return `<div class="panel tech-card ${locked?'locked':''}"><div class="flex spaced"><h3>${t.name}</h3>${chip(state.tech[t.id]?'已掌握':locked?'尚未公开':running?'研究中':'可研究',state.tech[t.id]?'':'orange')}</div><p>${t.desc}</p><div class="tech-card-footer"><small>${locked?t.date+' 公开':money(t.cost,0)+' 万 · '+t.weeks+' 周'}</small>${btn(state.tech[t.id]?'已完成':running?'正在研究':'投入研究','researchTech','small soft',`data-id="${t.id}" ${locked||state.tech[t.id]||running?'disabled':''}`)}</div></div>`;}).join('')}</div>`;}else body=`<div class="grid model-grid">${state.models.slice().reverse().map(modelCard).join('')}</div>`;return head('把想法带进实验室。','结构、材料、训练方式由你组合。多目标研发和并行项目始终开放。',btn(icon('book')+'研发入门','glossary','ghost'))+tabs+body;}
function helpButton(){return `<button class="help-button" data-action="glossary" title="查看名词与研发入门" aria-label="查看研发入门">?</button>`;}
function weightPercent(id){const total=E.sum(Object.entries(config.weights).filter(([id])=>state.inventory[id]).map(([,v])=>+v));return Math.round((config.weights[id]||0)/Math.max(1,total)*100);}
function mixVisual(){const total=E.sum(Object.entries(config.weights).filter(([id])=>state.inventory[id]).map(([,v])=>+v));return `<div class="mix-bar">${Object.entries(config.weights).filter(([id,w])=>state.inventory[id]&&w>0).map(([id,w],i)=>`<i style="width:${w/Math.max(1,total)*100}%;background:${DIM[i%DIM.length].color}" title="${esc(E.datasets(state).find(d=>d.id===id)?.name)} ${n(w/Math.max(1,total)*100)}%"></i>`).join('')}</div>`;}
function estimateHtml(){const e=E.estimate(state,config);const other=E.sum(state.projects.filter(p=>p.status==='running').map(p=>p.gpus));const share=Math.min(1,state.gpus/Math.max(1,other+Number(config.gpus)));return `<div><div class="small-text muted">实验启动投入</div><div class="estimate-cost">${money(e.cost)}<small>万</small></div></div><div><div class="estimate-row"><span class="muted">预计训练时间</span><strong>${n(Math.ceil(e.weeks/share))} 周</strong></div><div class="estimate-row"><span class="muted">激活参数</span><strong>${n(e.active,2)}B</strong></div></div><div class="divider"></div><div class="estimate-row"><span class="muted">材料抽样质量</span><strong>${n(e.quality)} / 100</strong></div><div class="estimate-row"><span class="muted">训练中断风险</span><strong class="${e.risk>.28?'negative':'orange'}">约 ${n(e.risk*100)}%</strong></div><div class="risk-track"><i style="left:${e.risk/.7*100}%"></i></div><div class="help">${e.tested?'该配置已有小实验记录，风险估计已下调。':'估计存在不确定性，可先用小实验验证。'}</div><ul class="hint-list">${e.warnings.map(w=>`<li>${w}</li>`).join('')}</ul><div class="divider"></div><div class="small-text muted">材料覆盖方向</div><div style="grid-column:1/-1;margin-top:12px">${caps(e.weights.map(w=>w*100))}</div><div class="help mt">以上表示材料方向，最终能力需要训练和评测确认。启动投入之外，当前算力租赁为每周 ${money(state.gpus*.18,2)} 万。</div><div class="estimate-actions">${btn('开始训练 '+icon('arrow'),'startTrain','primary',state.cash<e.cost?'disabled':'')}${btn('先跑小实验 · '+money(Math.max(2,e.cost*.22))+' 万','pilot','ghost',state.cash<Math.max(2,e.cost*.22)?'disabled':'')}</div>`;}
function updateEstimate(){const el=$('#estimate');if(el)el.innerHTML=estimateHtml();const mix=$('#mix-visual');if(mix)mix.innerHTML=mixVisual();for(const d of E.datasets(state)){const el=$('#weight-'+d.id);if(el)el.textContent=weightPercent(d.id)+'%';}}
function empty(title,desc,button='',action=''){return `<div class="empty">${icon('spark')}<h3>${title}</h3><p>${desc}</p>${button?btn(button,action,'small soft'):''}</div>`;}
function modelCard(m){return `<article class="panel model-card"><div class="model-card-top"><div class="model-heading"><div class="model-logo">${icon('cpu')}</div><div><h3>${esc(m.name)}</h3><p>${m.arch==='moe'?'MoE':'Dense'} · ${n(m.params,2)}B · ${m.context/1024}K CONTEXT</p></div></div>${chip(m.published?'已上线':'待发布',m.published?'':'orange')}</div>${caps(m.scores)}<div class="model-metrics"><div class="model-metric">${n(m.speed)}<small>响应速度指数</small></div><div class="model-metric">${compact(m.users)}<small>活跃用户</small></div><div class="model-metric">${m.published?'¥'+n(m.price):'—'}<small>月度订阅</small></div></div>${m.sourceRival?`<div class="own-source">${I.brand(RIVALS.find(r=>r.id===m.sourceRival))}基于 ${esc(RIVALS.find(r=>r.id===m.sourceRival)?.name)} 适配 · 公开基座来源保留</div>`:''}<div class="model-footer">${btn('对照同期模型','chooseOwn','small soft',`data-id="${m.id}"`)}${btn(m.published?'调整产品策略':'策划发布会','launch','small primary',`data-id="${m.id}"`)}${btn('运行评测','benchmark','small ghost',`data-id="${m.id}"`)}${btn('继续研发','iterate','small ghost',`data-id="${m.id}"`)}</div></article>`;}
function legacyDataPage(){const datasets=E.datasets(state).filter(d=>dataFilter==='all'||(dataFilter==='owned'?state.inventory[d.id]:!state.inventory[d.id]));return head('好模型，从好材料开始。','获取、整理与组合训练材料。已有数据可以被多条研发路线复用。',chip('已入库 '+Object.keys(state.inventory).length+' 份'))+`<div class="tabs">${[['all','全部材料'],['owned','我的仓库'],['available','可获取材料']].map(([id,label])=>`<button class="tab ${dataFilter===id?'active':''}" data-action="dataFilter" data-filter="${id}">${label}</button>`).join('')}</div><div class="grid data-grid">${datasets.map(d=>{const own=state.inventory[d.id],info=E.dataInfo(state,d.id),locked=!E.unlocked(state,d.date);return `<article class="panel data-card ${own?'owned':''} ${locked?'locked':''}"><div class="data-card-top"><div class="data-icon">${icon(d.id==='code'||d.id==='repair'?'code':d.id==='books'?'book':'data')}</div>${chip(own?'已入库':locked?'尚未开放':d.tag,own?'':'orange')}</div><h3>${d.name}</h3><p>${d.sample}</p><div class="data-stats"><div><strong>${n(info.tokens,1)}B</strong><span>材料规模 / tokens</span></div><div><strong>${n(info.quality)}</strong><span>抽样质量 / 100</span></div></div><div class="help" style="margin-bottom:16px">${d.source} · ${own?'可复用'+(own.clean?' · 已整理 '+own.clean+' 轮':''):locked?d.date+' 开放':'获取成本 '+money(d.cost,0)+' 万'}</div><div class="data-actions">${own?btn(own.clean>=2?'整理完成':'整理去重 · '+money((4+d.tokens*.3)*(state.tech.dataops?.8:1))+' 万','cleanData','small soft',`data-id="${d.id}" ${own.clean>=2?'disabled':''}`):btn(locked?'等待公开':d.cost?'获取材料 · '+money(d.cost,0)+' 万':'免费入库','buyData','small primary',`data-id="${d.id}" ${locked?'disabled':''}`)}${btn('查看','inspectData','small ghost',`data-id="${d.id}"`)}</div></article>`;}).join('')}</div><div class="notice mt">${icon('book')}<p>数据种类与规模用于经营模拟，质量为抽样估计。选择不同训练方式时，原始文本、任务示范和偏好反馈的作用有所不同。</p></div>`;}
function dataPage(){const body=legacyDataPage();return body.replace('<div class="tabs">',`<div class="data-hero-actions">${btn(icon('plus')+'委托采集新材料','commission','primary')}${btn(icon('copy')+'引入公开基座','publicBases','ghost')}</div><div class="tabs">`);}
function products(){return head('让实验，走到用户面前。','发布旗舰、专业版或轻量模型。每款产品都可以同时服务多个群体。',btn(icon('plus')+'研发新模型','builder','primary'))+`<div class="grid model-grid">${state.models.slice().reverse().map(modelCard).join('')}</div><section class="section-space panel">${panelHeader('评测档案',chip('游戏模拟分数'))}${state.benchmarks.length?`<div class="table-wrap"><table><thead><tr><th>模型 / 测试日期</th>${BENCHMARKS.map(b=>`<th title="${b.desc}">${b.name}</th>`).join('')}</tr></thead><tbody>${state.benchmarks.slice(0,8).map(r=>`<tr><td><strong>${esc(state.models.find(m=>m.id===r.model)?.name)}</strong><br><span class="backup-time">${r.date}</span></td>${BENCHMARKS.map(b=>`<td class="mono">${r.scores.some(x=>x.id===b.id)?n(r.scores.find(x=>x.id===b.id).score,1):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('第一份评测，等你来做','标准任务与社区测试会展示不同侧面的能力。每轮评测消耗 ¥1 万。')}</section>`;}
function legacyMarket(){return head('每一种用户，都有自己的期待。','免费体验带来尝试，真实体验决定留存。观察规模、付费、口碑和服务支出。',chip('品牌触达 '+compact(state.reach)))+`<div class="grid market-grid" style="grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;margin-bottom:22px">${SEGMENTS.map(g=>{const c=state.cohorts[g.id];return `<div class="panel market-segment"><div class="segment-top">${avatar(g.id)}<h3>${g.name}</h3></div><div class="segment-big">${compact(c.active)}</div><div class="help">潜在群体 ${compact(c.potential)}</div><p class="segment-desc">${g.desc}</p><div class="progress" style="margin-top:14px"><i style="width:${c.active?c.paid/c.active*100:0}%;background:${g.color}"></i></div><div class="segment-numbers"><span>付费 ${compact(c.paid)}</span><span>满意 ${n(c.satisfaction)}</span></div><div class="help mt">典型预算 ¥${g.budget}/月<br>群体付费倾向 ${n(g.pay*100)}%</div></div>`;}).join('')}</div><div class="grid two-col"><div class="stack"><form class="panel" data-form="marketing">${panelHeader('增长与免费补贴',chip('按周结算'))}<div class="panel-pad" style="padding-top:0"><div class="form-grid">${field('每周推广预算 · 万元',`<input type="number" name="marketing" min="0" max="300" step="0.5" value="${state.marketing}">`,'持续增加触达与尝试意愿。')}${field('免费服务每周补贴上限 · 万元',`<input type="number" name="freeCap" min="0" max="1000" step="0.5" value="${state.freeCap}">`,'额度越高，能够承接的免费体验越多。')}${field('用户邀请计划',`<label class="check-row" style="margin-top:8px"><input type="checkbox" name="referral" ${state.referral?'checked':''}>开启邀请奖励</label>`,'提高传播，每位净新增用户增加少量奖励成本。',true)}</div><div class="form-note">每人每天的免费次数，在各产品策略中设置。补贴上限会控制实际支出；触顶后限流，可能影响体验与口碑。</div><div class="flex spaced mt"><span class="help">设置从下一次推进生效。</span><button class="btn primary" type="submit">应用经营策略</button></div></div></form><div class="panel">${panelHeader('服务状况')}<div class="panel-pad" style="padding-top:0"><div class="grid budget-grid"><div><div class="help">本周免费体验成本</div><div class="stat-value" style="font-size:23px">${money(state.last.freeCost,2)}<small>万</small></div><div class="help">补贴上限 ${money(state.freeCap,1)} 万</div></div><div><div class="help">服务容量满足率</div><div class="stat-value ${state.last.capacity<.7?'negative':'positive'}" style="font-size:23px">${n(state.last.capacity*100)}<small>%</small></div><div class="help">可在公司页面调整算力。</div></div></div>${state.last.freeDelivery<.8?`<div class="notice warn mt" style="margin-bottom:0">${icon('alert')}<p>本周免费补贴触顶，实际承接约 ${n(state.last.freeDelivery*100)}% 的免费请求。可增加预算或下调产品免费次数。</p></div>`:''}</div></div></div><div class="stack"><div class="panel">${panelHeader('正在流动的需求')}<div class="panel-pad" style="padding-top:0">${state.trends.length?state.trends.map(t=>`<div class="trend-item"><div><h3>${esc(t.name)}</h3><p>${t.segment==='all'?'全部群体':SEGMENTS.find(g=>g.id===t.segment)?.name} · 还有 ${Math.max(0,t.until-state.week)} 周</p></div>${chip('尝试意愿 +'+n(t.effect*100)+'%','orange')}</div>`).join(''):empty('市场正在缓慢变化','人口规模随时间成长，历史事件和社区热点会带来新的需求。')}</div></div><div class="panel advisor"><div class="advisor-title"><div class="advisor-icon">↗</div>观察增长的质量</div><p>免费用户也会消耗算力。把新增、付费转化和每周支出放在一起看，才能知道活动是否值得持续。</p>${btn('调整产品额度','nav','small ghost','data-view="products"')}</div></div></div>`;}
function market(){const content=legacyMarket();return content.replace('<div class="grid market-grid"',`<div class="data-hero-actions">${btn(icon('spark')+'策划主题推广活动','promotions','primary')}${btn(icon('arena')+'看看用户眼中的对手','nav','ghost','data-view="arena"')}</div><div class="grid market-grid"`);}
function community(){const posts=state.posts.filter(p=>socialFilter==='all'||p.segment===socialFilter);const top=SEGMENTS.map(g=>({...g,c:state.cohorts[g.id]})).sort((a,b)=>b.c.active-a.c.active);return head('听见用户，也听见分歧。','程序员、数学与科研、普通用户、AIRP 玩家和企业团队，都有自己的评价。',btn(icon('spark')+(aiBusy?'生成中…':'AI 评论 / 风向'),'ai','ghost'))+`<div class="tabs">${[['all','全部声音'],...SEGMENTS.map(g=>[g.id,g.name])].map(([id,text])=>`<button class="tab ${socialFilter===id?'active':''}" data-action="socialFilter" data-filter="${id}">${text}</button>`).join('')}</div><div class="grid social-layout"><div class="panel">${posts.length?posts.map(p=>`<article class="post"><div class="post-head">${avatar(p.segment)}<div><div class="post-author">${esc(p.author)}</div><div class="post-meta">${p.date} · ${p.source==='ai'?'AI 文案 / 模拟用户':p.source==='history'?'真实历史事件':'模拟用户反馈'}</div></div>${p.source==='ai'?`<span class="chip blue" style="margin-left:auto">AI</span>`:''}</div><p class="post-content">${esc(p.text)}</p><div class="post-bottom"><button class="like-btn ${p.liked?'liked':''}" data-action="like" data-id="${p.id}" aria-label="${p.liked?'取消点赞':'点赞'}">${icon('heart')}${n(p.likes+(p.liked?1:0))}</button>${p.url?`<a class="small-text" href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">原始来源 ↗</a>`:''}<span class="sentiment ${p.sentiment==='positive'?'positive':p.sentiment==='negative'?'negative':'muted'}">${p.sentiment==='positive'?'正向体验':p.sentiment==='negative'?'提出问题':'观察与讨论'}</span></div></article>`).join(''):empty('这里还很安静','发布产品，或继续推进，等待这一群体的反馈。')}</div><aside class="stack"><div class="panel">${panelHeader('从声音到线索')}<div class="insight-list">${top.map(g=>`<div class="insight"><h3 style="color:${g.color}">${g.name} · ${n(g.c.satisfaction)} 满意度</h3><p>${!g.c.active?'尚无实际用户，当前为潜在需求讨论。':g.c.satisfaction>60?'体验较好，可以观察续费与更多实测。':'存在体验差距，建议结合专项测试调查。'}</p></div>`).join('')}</div></div><div class="panel advisor"><div class="advisor-title"><div class="advisor-icon">∑</div>邀请社区实测</div><p>为一款模型运行标准任务和社区专项评测，查看代码、数学和角色长聊的不同表现。</p>${btn('选择模型评测','chooseBench','small soft')}</div><div class="panel panel-pad"><div class="small-text">${icon('spark')} 可选 AI 接入</div><p class="help">默认反馈来自经营状态与用户群体。可接兼容接口生成评论；AI 提议的短期风向经过范围限制后生效。</p>${btn('配置接口','ai','small ghost')}</div></aside></div>`;}
function finance(){const offered=state.funding.filter(f=>f.status==='offered');return head('为下一次突破，留足跑道。','研发与融资可以同时推进。看清每周收支，也看清每轮融资后的股份。',chip('创始人持股 '+n(state.founder,1)+'%','orange'))+`${state.cash<0?`<div class="notice danger">${icon('alert')}<div><p>现金已不足，时间暂时停止。可以签署现有报价，或接受应急融资：获得 ¥180 万，出让本轮融资后 45% 股份。</p><div class="mt">${btn('查看应急融资','emergency','small danger')}</div></div></div>`:''}<div class="grid stats-grid">${stat('现金余额',n(state.cash,1),'万','包含训练、数据与融资影响','wallet')}${stat('每周固定开销',n(E.fixedBurn(state),2),'万',`薪资与办公 ${money(E.salary(state),2)} 万`,'finance')}${stat('上周经营净额',n(state.last.revenue-state.last.expense,2),'万',`收入 ${money(state.last.revenue,2)} / 支出 ${money(state.last.expense,2)}`,'market')}${stat('剩余经营时间',n(Math.max(0,E.runway(state))),'周','按当前经营收支估计','clock')}</div>${offered.map(f=>{const inv=INVESTORS.find(i=>i.id===f.investor);return `<div class="offer"><div class="offer-row"><strong>${inv.name} · 可签署报价</strong>${chip('投前估值 '+money(f.valuation,0)+' 万')}</div><div class="metric-inline"><div><strong>${money(f.amount,0)} 万</strong><small>本轮融资金额</small></div><div><strong>${n(f.share*100,1)}%</strong><small>投资人融资后持股</small></div><div><strong>${n(state.founder*(1-f.share),1)}%</strong><small>签署后创始人持股</small></div></div><p>${inv.desc} 本轮资金无强制罚款和债务条款，后续融资仍会考察经营成果。投资人名称与估值均为游戏模拟。</p>${btn('接受报价并到账','acceptFunding','small primary',`data-id="${f.id}"`)} ${btn('暂不接受','declineFunding','small ghost',`data-id="${f.id}"`)}</div>`;}).join('')}<h2 class="section-title">寻找同行者 <small>洽谈期间可自由经营</small></h2><div class="grid three-col">${INVESTORS.map(inv=>{const pending=state.funding.find(f=>f.investor===inv.id&&['pending','offered'].includes(f.status));return `<article class="panel investor" style="--c:${inv.color}"><div class="investor-icon">${inv.id==='technical'?'✧':inv.id==='growth'?'↗':'▦'}</div><h3>${inv.name}</h3>${chip(inv.tag)}<div class="amount">${money(inv.amount,0)}<small> 万</small></div><p>${inv.desc}</p>${btn(pending?pending.status==='offered'?'已有报价':'等待反馈 · '+Math.max(0,pending.due-state.week)+' 周':'开始洽谈 · '+inv.wait+' 周','applyFunding','wide ghost',`data-id="${inv.id}" ${pending?'disabled':''}`)}</article>`;}).join('')}</div><div class="grid two-col section-space"><div class="stack"><div class="panel">${panelHeader('团队与人才',chip(Object.values(state.team).reduce((a,b)=>a+b,1)+' 人（含创始人）'))}${ROLES.map(r=>`<div class="team-row"><div><h3>${r.name} <span class="mono muted">× ${state.team[r.id]}</span></h3><p>${r.desc} · 每周薪资 ${money(r.salary,2)} 万</p></div><div class="team-controls">${btn('招聘 · '+money(r.cost,0)+' 万','hire','small ghost',`data-id="${r.id}"`)}</div></div>`).join('')}</div><form class="panel" data-form="gpus">${panelHeader('算力租用',chip('训练与服务共享'))}<div class="panel-pad" style="padding-top:0"><div class="form-grid">${field('租用 GPU 数量',`<input type="number" name="gpus" value="${state.gpus}" min="1" max="512" step="1">`,'每张每周租赁 ¥0.18 万（游戏经济）。')}${field('当前每周租赁',`<div class="stat-value" style="font-size:24px;margin:4px 0">${money(state.gpus*.18,2)}<small>万</small></div>`)}</div><div class="flex spaced mt"><span class="help">调整即时生效，下周按新规模结算。</span><button class="btn primary" type="submit">调整算力</button></div></div></form></div><div class="stack"><div class="panel">${panelHeader('股份结构')}<div class="panel-pad" style="padding-top:0"><div class="finance-bars"><i style="width:${state.founder}%;background:var(--orange)"></i>${state.holders.map((h,i)=>`<i style="width:${h.share}%;background:${DIM[(i+1)%5].color}"></i>`).join('')}</div><div class="holding-row"><span>创始人 · 你</span><span class="mono orange">${n(state.founder,2)}%</span></div>${state.holders.map(h=>`<div class="holding-row"><span>${esc(h.name)}</span><span class="mono">${n(h.share,2)}%</span></div>`).join('')}<p class="help mt">每次新融资都会按比例稀释已有股东，报价接受前会展示你的最新持股。</p></div></div><div class="panel">${panelHeader('现金变化')}${chart(state.ledger,['cash'],['#e9a576'])}</div></div></div><section class="section-space panel">${panelHeader('公司纪事',chip('最近记录'))}${state.logs.slice(0,15).map(l=>`<div class="log-row"><div class="log-date">${l.date}</div><div class="log-content"><h3 class="${l.type==='danger'?'negative':''}">${esc(l.title)}</h3><p>${esc(l.body)}</p></div></div>`).join('')}</section>`;}
function historyPage(){const grouped={};for(const e of EVENTS){if(showFuture||date()>=e.date)(grouped[e.date.slice(0,4)]??=[]).push(e);}return head('在真实的历史里，走自己的路。','论文公开与产品发布沿真实日期推进。公司经营、市场规模和评测分数使用游戏模拟。',btn(showFuture?'收起未来事件':'查看完整年表','toggleFuture','ghost'))+`<div class="notice">${icon('history')}<p>历史节点收录至 2026 年 4 月，经营可自由继续。未来尚未发生的节点不会提前开放技术。事件带有原始来源，市场影响为游戏规则。</p></div>${Object.keys(grouped).length?Object.entries(grouped).map(([year,events])=>`<div class="history-year">${year}</div><div class="panel">${events.map(e=>`<article class="history-row ${date()<e.date?'historical-future':''}"><div class="history-date">${e.date}</div><div><h3>${e.title} ${date()<e.date?chip('尚未发生'):''}</h3><p>${e.desc}</p></div><a href="${e.url}" target="_blank" rel="noopener noreferrer">原始来源 ↗</a></article>`).join('')}</div>`).join(''):`<div class="panel">${empty('你的历史，刚刚开始','推进时间，行业论文、产品和社区变化将按日期出现。')}</div>`}<div class="section-space panel panel-pad"><div class="small-text">真实历史与游戏自由度</div><p class="help">真实公司的重要公开事件保留日期；你的公司、用户迁移、融资、成本和模型能力独立模拟。公开知识出现后，仍需要团队实现和实验验证。社区账号和帖子为模拟内容。</p></div>`;}
function render(){C.ensureCampaign(state);document.body.dataset.view=view;renderSidebar();renderTop();$('#main').innerHTML=`<div class="page">${({overview,research,arena,opportunities,data:dataPage,products,market,community,finance,history:historyPage}[view]||overview)()}</div>`;$('#footer').innerHTML=`<span>FRONTIER LAB / FOUNDER'S EDITION · ${date().slice(0,4)}</span><span>历史有据，经营与评测为游戏模拟 <button class="text-btn" data-action="historySources">资料说明 ↗</button></span>`;}
function go(id){view=titles[id]?id:'overview';render();window.scrollTo({top:0,behavior:'instant'});}
function modal(content,cls=''){const el=$('#modal');el.className=cls;el.innerHTML=content;if(!el.open)el.showModal();}
function modalHead(title,desc=''){return `<div class="modal-head"><div><h2 id="modal-title">${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${btn(icon('close'),'close','icon ghost','aria-label="关闭对话框"')}</div>`;}
function close(){$('#modal').close();}
function welcome(){modal(`<div class="welcome-top"><div class="eyebrow">FRONTIER LAB · A COMPANY SIMULATOR</div><h2>2022 年，<br>写下你的<span>下一种可能。</span></h2><p>从第一轮实验到第一场发布会。在真实 AI 历史中研发模型、选择材料、蒸馏、融资，听见不同用户的声音。</p><div class="welcome-facts"><div><strong>320<span style="font-size:13px"> 万</span></strong><small>启动资金</small></div><div><strong>4<span style="font-size:13px"> 人</span></strong><small>创始团队</small></div><div><strong>∞</strong><small>你的研发路线</small></div></div></div><form class="welcome-form" data-form="welcome"><div class="field"><label>先给公司起个名字</label><input name="company" value="${esc(state.company)}" maxlength="24" placeholder="你的 AI 公司" required></div><button class="btn primary wide" type="submit">进入 2022 年，开始创业 ${icon('arrow')}</button><p class="welcome-note">可自由并行研发、经营与融资。进度自动保存在当前浏览器，可随时导出。</p></form>`,'welcome');}
function launchModal(id){const m=state.models.find(m=>m.id===id);modal(`${modalHead(m.published?'调整产品策略':'策划你的发布会','产品面向所有用户开放；推广重点可以同时选择多个群体。')}<form data-form="launch" data-id="${m.id}"><div class="modal-body"><div class="launch-stage"><small>${esc(state.company)} / PRODUCT RELEASE</small><h3>${esc(m.name)}</h3><p>${m.arch==='moe'?'MIXTURE OF EXPERTS':'DENSE TRANSFORMER'} · ${n(m.params,2)}B · ${m.context/1024}K CONTEXT</p></div><div class="form-grid">${field('订阅月费 · 元',`<input type="number" name="price" value="${m.price}" min="0" max="9999" step="1">`,'设为 0 可作为免费产品运营。')}${field('每人每天免费次数',`<input type="number" name="quota" value="${m.quota}" min="0" max="10000" step="5">`,'实际承接量受公司免费补贴上限影响。')}${!m.published?field('发布会投入 · 万元',`<input type="number" name="budget" value="5" min="0" max="100" step="1">`,'也可以零预算直接上线。')+field('宣传力度',`<select name="claim"><option value="0">克制 · 按实测介绍</option><option value="10">积极 · 强调产品优势</option><option value="25">高调 · 抬高公众预期</option></select>`,'高调宣传带来注意，也会引来更严格的审视。'):''}${field('推广关注群体',`<div class="check-chips">${SEGMENTS.map(g=>`<label class="check-chip"><input type="checkbox" name="target" value="${g.id}" ${m.targets.includes(g.id)?'checked':''}>${g.name}</label>`).join('')}</div>`,'勾选影响推广方向，不限制其他用户使用。',true)}</div><div class="form-note">当前每周免费补贴上限 ${money(state.freeCap,1)} 万，推广预算 ${money(state.marketing,1)} 万。可在“用户与增长”随时调整。</div></div><div class="modal-footer">${btn('再想想','close','ghost')}<button class="btn primary" type="submit">${m.published?'保存产品策略':'举办发布会并上线'}</button></div></form>`);}
function glossary(){modal(`${modalHead('研发入门手册','随时查看，随时跳过。你可以先用推荐方案，再逐步理解细节。')}<div class="modal-body"><div class="notice">${icon('spark')}<p>一个基础模型可以发展多个版本。结构、材料、训练方式和投入共同决定结果；小实验可以帮助减少未知。</p></div><div class="glossary">${GLOSSARY.map(([name,desc])=>`<div><h3>${name}</h3><p>${desc}</p></div>`).join('')}</div><details class="details"><summary>第一次可以怎样开始？</summary><p>在训练材料里获取代码或角色对话 → 回到模型实验台选择“代码与创作，两手抓” → 自由调整比例 → 开始训练 → 推进一周或更多 → 到模型库评测与发布。过程中可以同时寻找投资、招聘或启动其他项目。</p></details></div><div class="modal-footer">${btn('回到工作台','close','primary')}</div>`);}
function settings(){modal(`${modalHead('设置与存档','进度保存在当前浏览器，导出存档可以备份或转移到其他设备。')}<div class="modal-body"><form data-form="company"><div class="field"><label>公司名称</label><input name="company" value="${esc(state.company)}" maxlength="24" required></div><div class="mt"><button class="btn small soft" type="submit">保存名称</button></div></form><hr class="settings-divider"><div class="settings-actions">${btn(icon('download')+'导出存档','export','ghost')}${btn('导入存档','import','ghost')}${btn(icon('spark')+'AI 接口','ai','ghost')}</div><p class="help mt">存档包含公司、模型、数据、融资与全部经营记录。接口密钥不会写入存档。</p><div class="danger-zone"><h3>重新开始</h3><p>当前浏览器的游戏进度将被替换，建议先导出备份。</p>${btn('创建新游戏','resetConfirm','small danger')}</div></div><div class="modal-footer">${btn('完成','close','primary')}</div>`);}
function aiModal(){modal(`${modalHead('让社区拥有更多声音','可选功能。未配置接口时，游戏使用经营数据驱动的模拟评论。')}<form data-form="ai"><div class="modal-body"><div class="form-grid">${field('兼容接口 Base URL',`<input type="url" name="endpoint" placeholder="https://your-service.example/v1 或 http://localhost:11434" value="${esc(aiConfig.endpoint||'')}" required>`,'支持 HTTP / HTTPS、OpenAI 兼容服务、Ollama 和 LM Studio。填完地址与密钥后自动获取模型。',true)}${field('API Key（如接口需要）',`<input type="password" name="key" value="${esc(aiKey)}" placeholder="本地服务可留空 · 仅保留在页面内存" autocomplete="off">`,'密钥不进入游戏存档；刷新后需要重新填写。',true)}<div class="field full ai-model-picker"><div class="flex spaced"><label for="ai-model-select">服务提供的模型</label>${btn('刷新模型列表','fetchModels','small soft','id="ai-fetch-models"')}</div><select id="ai-model-select" name="detected-model" aria-label="已获取的模型"></select><small id="ai-model-status" role="status" aria-live="polite"></small></div>${field('模型 ID（可手动填写）',`<input name="model" value="${esc(aiConfig.model||'')}" placeholder="自动读取后可选择，也可以直接输入" required>`,'模型列表接口不可用时，手动填写仍可生成评论。',true)}${field('可选的短期风向',`<label class="check-row"><input type="checkbox" name="trend" ${aiConfig.trend?'checked':''}>允许 AI 同时提议一次社区风向</label>`,'每次最多影响一个群体，尝试意愿增加 3%–20%，持续 2–6 周。',true)}</div><div class="form-note ai-network-note"><strong>HTTP 与本地服务</strong><p id="ai-network-status">HTTPS 网页连接普通 HTTP 服务可能被浏览器拦截。本机与局域网服务还需允许本地网络访问及跨域请求。</p><a href="./downloads/frontier-lab-local.zip" download>下载本地连接版 ↗</a><small>电脑解压后运行 start-local.py（需 Python 3），自动打开游戏；内置本机转发，支持 HTTP 与跨域接口。换地址玩之前可先导出存档。</small></div><div class="form-note">获取列表只读取模型名称。点击生成才会向你配置的服务发送游戏内模型能力、用户统计和近期动态，并可能产生接口费用。AI 文案仅代表模拟用户。</div><div id="ai-status" class="help mt">${aiBusy?'正在等待接口返回…':'每次生成 5 条评论，标注为 AI 文案。'}</div></div><div class="modal-footer">${btn('保存配置','saveAi','ghost')}<button class="btn primary" type="submit" ${aiBusy?'disabled':''}>${aiBusy?'正在生成…':'保存并生成评论'}</button></div></form>`);updateAiModelUI();localBridgeAvailable().then(ready=>{const el=$('#ai-network-status');if(ready&&el)el.textContent='本地连接器已就绪 · HTTP / HTTPS 请求通过本机转发，无需为接口单独设置浏览器跨域。';});}
function captureAiForm(requireModel=false,persist=false){const form=$('[data-form="ai"]');if(!form)return false;const f=new FormData(form);let endpoint;try{endpoint=normalizeEndpoint(f.get('endpoint'));}catch(error){toast(error.message,true);return false;}aiKey=String(f.get('key')||'').trim();aiConfig={endpoint,model:String(f.get('model')||'').trim(),trend:f.has('trend')};if(requireModel&&!aiConfig.model){toast('请选择一个模型，或手动填写模型 ID。',true);return false;}if(persist)try{localStorage.setItem('frontier-ai-config',JSON.stringify(aiConfig));}catch{}return true;}
function readAiForm(){return captureAiForm(true,true);}
function updateAiModelUI(){const picker=$('#ai-model-select'),status=$('#ai-model-status'),button=$('#ai-fetch-models');if(!picker)return;picker.innerHTML=option('',aiModelsBusy?'正在读取…':aiModels.length?'选择服务提供的模型':'等待读取，也可手动填写')+aiModels.map(id=>option(id,id,id===aiConfig.model)).join('');picker.disabled=!aiModels.length||aiModelsBusy;if(status)status.textContent=aiModelStatus;if(button){button.disabled=aiModelsBusy;button.textContent=aiModelsBusy?'读取中…':'刷新模型列表';}}
async function fetchAiModels(){clearTimeout(aiDiscoveryTimer);if(!captureAiForm())return;aiDiscoveryController?.abort();const id=++aiDiscoveryId,endpoint=aiConfig.endpoint,key=aiKey,controller=new AbortController();aiDiscoveryController=controller;const timer=setTimeout(()=>controller.abort(),20000);aiModels=[];aiModelsBusy=true;aiModelStatus='正在连接服务并读取模型名称…';updateAiModelUI();try{const found=await discoverModels(endpoint,key,{signal:controller.signal});if(id!==aiDiscoveryId)return;aiConfig.endpoint=found.endpoint;aiModels=found.models;const form=$('[data-form="ai"]');if(form){const input=form.elements.namedItem('model');if(!input.value||!aiModels.includes(input.value))input.value=aiModels[0];aiConfig.model=input.value;form.elements.namedItem('endpoint').value=found.endpoint;}aiModelStatus='已连接 · 获取到 '+aiModels.length+' 个模型，请从列表选择或手动修改。';}catch(error){if(id!==aiDiscoveryId)return;aiModelStatus=connectionError(error,endpoint,location.protocol);}finally{clearTimeout(timer);if(id===aiDiscoveryId){aiModelsBusy=false;updateAiModelUI();}}}
document.addEventListener('input',event=>{const el=event.target;if(el.closest('[data-form="ai"]')&&['endpoint','key'].includes(el.name)){aiDiscoveryController?.abort();aiDiscoveryId++;aiModelsBusy=false;aiModels=[];aiModelStatus='填完地址与密钥后自动读取，也可以点刷新模型列表。';updateAiModelUI();clearTimeout(aiDiscoveryTimer);try{normalizeEndpoint($('[data-form="ai"] [name="endpoint"]').value);aiDiscoveryTimer=setTimeout(()=>{if($('[data-form="ai"]'))fetchAiModels();},800);}catch{}}});
document.addEventListener('change',event=>{const el=event.target;if(!el.closest('[data-form="ai"]'))return;if(el.name==='endpoint'||el.name==='key'){if($('[data-form="ai"] [name="endpoint"]').value.trim())fetchAiModels();}else if(el.name==='detected-model'&&el.value){$('[data-form="ai"] [name="model"]').value=el.value;aiConfig.model=el.value;}});
async function generateAi(){if(aiBusy||!readAiForm())return;aiBusy=true;aiModal();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);try{const context={date:date(),company:state.company,models:state.models.filter(m=>m.published).map(m=>({name:m.name,scores:Object.fromEntries(DIM.map((d,i)=>[d.name,Math.round(m.scores[i])])),price:m.price,dailyFreeQuota:m.quota})),cohorts:SEGMENTS.map(g=>({id:g.id,name:g.name,active:state.cohorts[g.id].active,satisfaction:Math.round(state.cohorts[g.id].satisfaction)})),capacity:state.last.capacity,freeDelivery:state.last.freeDelivery??1,recent:state.logs.slice(0,4).map(l=>l.title)};const prompt='你为一款 AI 公司经营游戏撰写虚构社区反馈。只能依据所给游戏状态，不编造现实新闻、官方评测分数、个人经历证据或未发布产品。五类用户各写一条，具体、自然、有不同观点，中文。没有上线模型时写需求与期待，不声称已经使用。仅返回 JSON：{"posts":[{"segment":"dev|science|everyday|rp|business","author":"虚构昵称","text":"最多120字","sentiment":"positive|neutral|negative"}]'+(aiConfig.trend?',"trend":{"segment":"dev|science|everyday|rp|business","title":"一个虚构社区需求热点，非现实新闻","effect":0.1,"weeks":4}':'')+'}。状态：'+JSON.stringify(context);const url=aiConfig.endpoint.endsWith('/chat/completions')?aiConfig.endpoint:aiConfig.endpoint+'/chat/completions';const response=await apiRequest(url,{method:'POST',headers:{'Content-Type':'application/json',...(aiKey?{Authorization:'Bearer '+aiKey}:{})},body:JSON.stringify({model:aiConfig.model,messages:[{role:'user',content:prompt}],temperature:.85,max_tokens:1800}),signal:controller.signal});if(!response.ok)throw new Error('接口返回 HTTP '+response.status);const payload=await response.json();let text=payload.choices?.[0]?.message?.content;if(typeof text!=='string')throw new Error('接口未返回兼容的消息内容');text=text.replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,'').trim();const parsed=JSON.parse(text.slice(text.indexOf('{'),text.lastIndexOf('}')+1));if(!Array.isArray(parsed.posts)||!parsed.posts.length)throw new Error('没有读取到评论数组');let count=0;for(const p of parsed.posts.slice(0,5)){if(!SEGMENTS.some(g=>g.id===p.segment)||typeof p.text!=='string'||!p.text.trim())continue;E.addPost(state,p.segment,String(p.author||'社区用户').slice(0,30)+' / AI 模拟',p.text.slice(0,350),['positive','negative'].includes(p.sentiment)?p.sentiment:'neutral',{source:'ai'});count++;}if(!count)throw new Error('评论格式未通过检查');if(aiConfig.trend&&parsed.trend&&SEGMENTS.some(g=>g.id===parsed.trend.segment)){const t=parsed.trend;state.trends.push({id:'ai-trend-'+(++state.serial),name:String(t.title||'社区讨论热点').slice(0,50)+' · AI 模拟',segment:t.segment,effect:E.clamp(Number(t.effect)||.10,.03,.20),until:state.week+E.clamp(Math.round(Number(t.weeks)||4),2,6)});}E.log(state,'AI 社区内容已生成',count+' 条模拟评论已加入社区。','info');save();close();go('community');toast('已生成 '+count+' 条 AI 模拟评论。');}catch(err){toast(err.name==='AbortError'?'请求超时，游戏进度未受影响。':connectionError(err,aiConfig.endpoint,location.protocol),true);}finally{clearTimeout(timer);aiBusy=false;renderTop();const form=$('[data-form="ai"]');if(form)aiModal();}}
function advance(count=1){const counterBefore={cash:state.cash,users:E.totalUsers(state),influence:state.influence,projects:state.projects.filter(p=>p.status==='running').length};const oldIds=new Set(state.logs.map(l=>l.id));let advanced=0;for(let i=0;i<count;i++){const r=C.advance(state);if(r.error){toast(r.error,true);break;}advanced++;}save();render();if(advanced){const important=state.logs.filter(l=>!oldIds.has(l.id)&&['danger','success','history','funding'].includes(l.type));const latest=important[0];toast(latest?latest.title:`第 ${state.week+1} 周 · ${state.last.newUsers>=0?'+':''}${n(state.last.newUsers)} 位用户`,latest?.type==='danger');animateHQMetrics(counterBefore);document.body.classList.add('week-jump');setTimeout(()=>document.body.classList.remove('week-jump'),750);const report=state.campaign.lastWeek;if(!autoTimer&&report&&(report.released.length||report.completed.some(id=>state.projects.find(p=>p.id===id)?.type==='train')||report.milestones.length)){modal(I.weekReport(state,report),'week-modal');}playTone('week');}}
function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='frontier-lab-'+date()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('存档已导出。');}
function confirmDialog(title,desc,action,text){modal(`${modalHead(title)}<div class="modal-body"><p class="small-text muted">${desc}</p></div><div class="modal-footer">${btn('取消','close','ghost')}${btn(text,action,'danger')}</div>`);}
function applyPreset(preset){config=E.defaultConfig(state);const best=state.models.slice().sort((a,b)=>E.sum(b.scores)-E.sum(a.scores))[0];config.base=best.id;if(preset==='both'){config.name='潮汐 Duo-'+state.models.length;config.weights={web:15,dialogue:25,code:30,roleplay:30};config.volume=1;config.mode='sft';}else if(preset==='scratch'){config.name='潮汐 Base-'+state.models.length;config.mode='scratch';config.params=1.3;config.volume=12;config.weights={web:45,books:20,code:20,math:15};}else if(preset==='distill'){config.name='潮汐 Mini-'+state.models.length;config.mode='distill';config.params=.7;config.teacher=best.id;config.weights={web:15,dialogue:40,code:20,roleplay:25};config.volume=1;}const available=Object.entries(config.weights).filter(([id])=>state.inventory[id]);if(!available.some(([,w])=>w>0))config.weights={web:50,dialogue:50};researchTab='builder';go('research');if(preset==='both'&&(!state.inventory.code||!state.inventory.roleplay))toast('方案已填好。获取代码或角色材料后，可直接调整对应配比。');}
$('#main').addEventListener('input',event=>{const el=event.target;if(el.dataset.config){const key=el.dataset.config;config[key]=el.type==='checkbox'?el.checked:el.type==='number'||['context','experts','topK'].includes(key)?Number(el.value):el.value;updateEstimate();}if(el.dataset.weight){config.weights[el.dataset.weight]=Number(el.value);updateEstimate();}});
$('#main').addEventListener('change',event=>{const el=event.target;if(el.dataset.config){const key=el.dataset.config;if(['mode','base','arch'].includes(key)){if(key==='mode'&&config.mode==='scratch'&&config.volume<2)config.volume=12;render();}else updateEstimate();}});
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;try{switch(action){
 case 'nav':close();if(el.dataset.view==='research')researchTab=state.projects.some(p=>p.status==='failed')?'projects':'builder';go(el.dataset.view);break;
 case 'close':close();break;
 case 'builder':researchTab='builder';go('research');break;
 case 'researchTab':researchTab=el.dataset.tab;render();break;
 case 'dataFilter':dataFilter=el.dataset.filter;render();break;
 case 'socialFilter':socialFilter=el.dataset.filter;render();break;
 case 'preset':applyPreset(el.dataset.preset);break;
 case 'inbox':showInbox();break;
 case 'eventChoice':{const result=C.chooseEvent(state,id,el.dataset.choice);if(!result.error){save();close();render();toast(result.text);playTone('choice');if(result.preset)applyPreset(result.preset);else if(result.launch)launchModal(result.launch);else if(result.navigate){if(result.rival)arenaRival=result.rival;go(result.navigate);}if(result.report)reportModal(result.report);}else toast(result.error,true);break;}
 case 'person':showPerson(el.dataset.person);break;
 case 'news':showNews(id);break;
 case 'arenaTab':arenaTab=el.dataset.tab;render();break;
 case 'rankGroup':rankGroup=el.dataset.group;render();break;
 case 'arenaCompare':arenaTab='compare';go('arena');break;
 case 'compareRival':arenaRival=id;arenaTab='compare';close();go('arena');break;
 case 'chooseOwn':arenaOwn=id;arenaTab='compare';close();go('arena');break;
 case 'quickDuel':close();if(el.dataset.own)arenaOwn=el.dataset.own;arenaTab='compare';go('arena');break;
 case 'startDuel':{const result=C.runDuel(state,el.dataset.own,el.dataset.rival);if(result.error){toast(result.error,true);break;}save();render();const d=result.battle;modal(I.duelLoading(state,d),'duel-modal');playTone('start');if(duelTimer)clearTimeout(duelTimer);duelTimer=setTimeout(()=>{if($('#modal').open&&$('#modal').querySelector('.duel-loading'))modal(I.duelBlind(state,d),'duel-modal');},1800);break;}
 case 'duelBlind':{const d=state.campaign.duels.find(d=>d.id===id);if(d){if(duelTimer)clearTimeout(duelTimer);modal(I.duelBlind(state,d),'duel-modal');}break;}
 case 'duelSample':{const d=state.campaign.duels.find(d=>d.id===id);if(d)modal(I.duelBlind(state,d,Number(el.dataset.task)||0),'duel-modal');break;}
 case 'duelResults':{const d=state.campaign.duels.find(d=>d.id===id);if(d){if(duelTimer)clearTimeout(duelTimer);modal(I.duelResults(state,d),'duel-modal');playTone(d.winner==='you'?'win':'reveal');}break;}
 case 'learnDuel':learnFromDuel(id);break;
 case 'quickLaunch':{close();const m=state.models.find(m=>!m.published&&m.id!==state.models[0].id)||state.models.at(-1);launchModal(m.id);break;}
 case 'acceptContract':{const r=C.acceptContract(state,id);act(r,r.error?null:'合作已接下，可以和其他项目同时推进。');break;}
 case 'claimContract':{const r=C.claimContract(state,id);if(act(r,r.error?null:'合作款 ¥'+r.reward+' 万已经到账。'))playTone('win');break;}
 case 'contractPrepare':{const def=C.CONTRACTS.find(d=>d.id===id);if(def?.kind==='duel'){arenaTab='compare';go('arena');}else {researchTab='builder';go('research');}break;}
 case 'commission':commissionModal();break;
 case 'publicBases':publicBasesModal();break;
 case 'importBase':{const result=C.importBase(state,id);if(!result.error){save();close();go('overview');toast('基座开始集成，完成后可继续训练和蒸馏。');playTone('start');}else toast(result.error,true);break;}
 case 'promotions':promotionsModal();break;
 case 'startPromotion':{const result=C.startPromotion(state,id);if(!result.error){save();close();render();toast('主题活动开始了，接下来观察用户与服务表现。');playTone('choice');}else toast(result.error,true);break;}
 case 'sound':toggleSound();break;
 case 'advance':advance();break;
 case 'advanceMenu':modal(`${modalHead('时间由你掌握','时间暂停时可以自由设计、调整策略和比较方案。')}<div class="modal-body"><div class="settings-actions">${btn('推进 4 周','advanceFour','primary')}${btn(autoTimer?'停止自动推进':'每 3 秒推进一周','toggleAuto','ghost')}</div><p class="help mt">按空格也可以推进一周。自动推进会在现金不足时停止。</p></div>`);break;
 case 'advanceFour':close();advance(4);break;
 case 'toggleAuto':if(autoTimer){clearInterval(autoTimer);autoTimer=null;}else autoTimer=setInterval(()=>{if(state.cash<0||$('#modal').open){if(state.cash<0){clearInterval(autoTimer);autoTimer=null;renderTop();}return;}advance();},3000);close();renderTop();break;
 case 'startTrain':case 'pilot':{const result=E.startTraining(state,structuredClone(config),action==='pilot');if(act(result,action==='pilot'?'小实验已启动，推进时间查看结果。':'训练已启动，可以同时做其他事情。')){researchTab='projects';go('overview');playTone('start');}break;}
 case 'resume':act(E.resumeTraining(state,id),'项目已恢复。');break;
 case 'pauseProject':{const p=state.projects.find(p=>p.id===id);if(p?.status==='running'){p.status='paused';E.log(state,'项目已暂停',p.name+' 暂停使用训练算力。');save();render();}break;}
 case 'unpauseProject':{const p=state.projects.find(p=>p.id===id);if(p?.status==='paused'){p.status='running';save();render();}break;}
 case 'cloneProject':{const p=state.projects.find(p=>p.id===id);if(p?.config){config=structuredClone(p.config);researchTab='builder';go('research');}break;}
 case 'buyData':act(E.buyData(state,id),'材料已入库，可以在研发中自由配比。');break;
 case 'cleanData':act(E.cleanData(state,id),'材料整理完成。');break;
 case 'inspectData':{const d=E.dataInfo(state,id);modal(`${modalHead(d.name,d.tag+' · '+d.source)}<div class="modal-body"><div class="metric-inline"><div><strong>${n(d.tokens,1)}B</strong><small>材料规模 / tokens</small></div><div><strong>${n(d.quality)}</strong><small>抽样质量</small></div><div><strong>${n(d.noise*100)}%</strong><small>估计噪声</small></div></div><div class="form-note mt">${d.sample}</div><p class="help mt">材料为游戏内数据包，规模与质量使用模拟值。低质、重复或单一内容可能影响效果。入库后可以清洗，也可以搭配其他材料使用。</p><div class="mt">${caps(d.weights.map(w=>w*100))}</div></div><div class="modal-footer">${btn('返回','close','primary')}</div>`);break;}
 case 'researchTech':act(E.startResearch(state,id),'工程研究已启动。');break;
 case 'benchmark':{const r=E.benchmark(state,id);if(act(r)){C.checkContracts(state);save();reportModal(r.result);}break;}
 case 'launch':launchModal(id);break;
 case 'iterate':config=E.defaultConfig(state);config.base=id;config.name=state.models.find(m=>m.id===id).name.replace(/ · 研究原型/,'')+' Next';researchTab='builder';go('research');break;
 case 'applyFunding':act(E.applyFunding(state,id),'融资洽谈已启动，继续推进时间等待反馈。');break;
 case 'acceptFunding':act(E.acceptFunding(state,id),'融资已到账，股权结构已更新。');break;
 case 'declineFunding':{const f=state.funding.find(f=>f.id===id);if(f?.status==='offered'){f.status='declined';save();render();toast('已拒绝本次报价，可继续寻找其他方案。');}break;}
 case 'emergency':confirmDialog('接受应急融资？','获得 ¥180 万，出让本轮融资后 45% 股份。你及现有投资人的比例会一起稀释。','confirmEmergency','接受并继续经营');break;
 case 'confirmEmergency':close();act(E.emergencyFunding(state),'应急资金已到账。');break;
 case 'hire':act(E.hire(state,id),'新同事已加入。');break;
 case 'like':{const p=state.posts.find(p=>p.id===id);if(p){p.liked=!p.liked;save();render();}break;}
 case 'chooseBench':modal(`${modalHead('选择实测模型','每轮评测消耗 ¥1 万，包含标准任务与社区专项。')}<div class="modal-body stack">${state.models.map(m=>btn(esc(m.name)+' '+icon('arrow'),'benchmark','ghost',`data-id="${m.id}"`)).join('')}</div>`);break;
 case 'settings':settings();break;
 case 'glossary':glossary();break;
 case 'ai':aiModal();break;
 case 'fetchModels':fetchAiModels();break;
 case 'saveAi':if(readAiForm())toast('接口配置已保存，密钥仅保留在本页面。');break;
 case 'export':exportSave();break;
 case 'import':$('#import-file').click();break;
 case 'resetConfirm':confirmDialog('重新开始游戏？','当前浏览器的进度将被新游戏替换。请先导出存档，保留现有公司。','reset','重新开始');break;
 case 'reset':stopAmbient();if(autoTimer){clearInterval(autoTimer);autoTimer=null;}state=E.initialState();C.ensureCampaign(state);config=E.defaultConfig(state);arenaOwn=state.models.at(-1).id;arenaRival='';save();close();go('overview');welcome();break;
 case 'toggleFuture':showFuture=!showFuture;render();break;
 case 'historySources':close();go('history');break;
 }}catch(error){console.error(error);toast('操作未完成：'+error.message,true);}});
function reportModal(r){const m=state.models.find(m=>m.id===r.model);modal(`${modalHead('评测完成 · '+esc(m.name),'标准任务与真实使用关注点不同，建议结合多种结果判断。')}<div class="modal-body"><div class="notice">${icon('book')}<p>以下分数由游戏能力模型生成，用于局内比较，不能作为现实模型的官方 Benchmark 成绩。</p></div>${r.scores.map(x=>{const b=BENCHMARKS.find(b=>b.id===x.id);return `<div class="estimate-row"><div>${b.name}<div class="help">${b.desc}</div></div><strong style="color:var(--orange);font-size:22px">${n(x.score,1)}</strong></div><div class="progress" style="margin-bottom:19px"><i style="width:${x.score}%"></i></div>`;}).join('')}</div><div class="modal-footer">${btn('与同期模型对照','chooseOwn','ghost',`data-id="${m.id}"`)}${btn('查看评测档案','nav','ghost','data-view="products"')}${btn('策划产品发布','launch','primary',`data-id="${m.id}"`)}</div>`);}
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const f=new FormData(form);switch(form.dataset.form){case 'welcome':state.company=String(f.get('company')||'潮汐智能').trim().slice(0,24)||'潮汐智能';state.started=true;save();close();render();toast('欢迎来到 2022 年。时间由你推进，自由开始第一轮实验。');break;case 'company':state.company=String(f.get('company')||'潮汐智能').trim().slice(0,24)||'潮汐智能';save();render();toast('公司名称已更新。');break;case 'marketing':state.marketing=E.clamp(Number(f.get('marketing'))||0,0,300);state.freeCap=E.clamp(Number(f.get('freeCap'))||0,0,1000);state.referral=f.has('referral');save();render();toast('经营策略已应用，下周按新设置结算。');break;case 'commission':{const result=C.commissionData(state,{name:f.get('name'),tokens:f.get('tokens'),source:f.get('source'),format:f.get('format'),focus:f.getAll('focus')});if(result.error){toast(result.error,true);break;}save();close();go('overview');toast('材料采集开始，完成后会自动入库。');playTone('start');break;}case 'gpus':state.gpus=E.clamp(Math.round(Number(f.get('gpus')))||1,1,512);save();render();toast('算力规模已更新。');break;case 'launch':{const was=state.models.find(m=>m.id===form.dataset.id)?.published;const r=E.publishModel(state,form.dataset.id,{price:f.get('price'),quota:f.get('quota'),budget:was?0:f.get('budget'),claim:was?0:f.get('claim'),targets:f.getAll('target')});if(r.error){toast(r.error,true);break;}if(!was)C.published(state,form.dataset.id);save();close();go('products');if(!was){modal(I.releaseShow(state,state.models.find(m=>m.id===form.dataset.id)),'release-modal');playTone('reveal');}else toast('产品策略已更新。');break;}case 'ai':generateAi();break;}});
$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('存档文件过大');const data=JSON.parse(await file.text());if(!E.validateSave(data))throw new Error('不是可识别的前沿实验室存档');if(autoTimer){clearInterval(autoTimer);autoTimer=null;}state=data;C.ensureCampaign(state);config=E.defaultConfig(state);arenaOwn=state.models.at(-1).id;arenaRival='';save();close();go('overview');toast('存档已恢复。');}catch(error){toast(error.message,true);}event.target.value='';});
document.addEventListener('keydown',event=>{if(['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName)||$('#modal').open)return;if(event.code==='Space'){event.preventDefault();advance();}if(event.key.toLowerCase()==='r'){researchTab='builder';go('research');}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom){if(state.started)close();}}});
$('#modal').addEventListener('cancel',event=>{if(!state.started)event.preventDefault();});
function showInbox(){const pending=state.campaign.events.filter(e=>e.status==='pending');modal(`${modalHead('桌上的来信','这些决定可以暂缓，研发和经营仍可照常推进。')}<div class="modal-body inbox-stack">${pending.length?pending.map(e=>I.choiceCard(state,e)).join(''):'<div class="narrative-empty">暂时没有新的来信。<br>团队正忙着各自的工作，新的机会会随着日历到来。</div>'}</div>`,'inbox-modal');}
function showPerson(id){const p=C.PEOPLE[id]||C.PEOPLE.researcher;let line=p.line;if(id==='engineer'&&state.last.capacity<.7)line='请求比上周多了，队列还在变长。我可以接更多 GPU，也可以先把免费次数收一收。你更想怎么做？';if(id==='researcher'){const m=state.models.at(-1),r=C.nearestRival(state,m);line='我看了 '+r.name+' 的对照。我们可以在某个用途先胜过它，也可以把时间投入自己的架构。下一轮实验，你想先验证什么？';}if(id==='community'&&state.campaign.duels.length){const d=state.campaign.duels[0];line='最近那场盲测，有 '+d.votes+' 人选了我们的模型。有些人看代码，有些人只在乎文风。我们得知道，是谁在选择我们。';}modal(`${modalHead(p.name,p.role)}<div class="modal-body"><div class="person-dialogue">${I.face(id)}<div><h3>${p.name}</h3><small>${p.role} · 公司同事</small><p>“${esc(line)}”</p></div></div><div class="person-dialogue-actions">${btn('回去继续工作','close','ghost')}${btn(id==='investor'?'聊聊融资':id==='engineer'?'看看机房':id==='community'?'去听听社区':'下一轮实验','nav','primary',`data-view="${id==='investor'||id==='engineer'?'finance':id==='community'?'community':'research'}"`)}</div></div>`);}
function showNews(id){const news=state.campaign.news.find(n=>n.id===id);if(!news)return;modal(`${modalHead(news.tag+' · '+news.date)}<div class="modal-body"><h2 style="font-size:24px;font-weight:500;line-height:1.7;margin-top:0">${esc(news.title)}</h2><p class="help" style="font-size:12px;line-height:2">${esc(news.body)}</p><div class="mt">${news.rival?btn('看看这个对手','compareRival','primary',`data-id="${news.rival}"`):news.duel?btn('回看这场盲测','duelResults','primary',`data-id="${news.duel}"`):btn('回到总部','nav','primary','data-view="overview"')}</div></div>`);}
function publicBasesModal(){const bases=C.publicBases(state);modal(`${modalHead('把公开基座，带进实验室。','只出现当前时间线已有的可引入模型；集成费用、时间和能力使用游戏模拟。')}<div class="modal-body"><div class="public-base-list">${bases.map(r=>{const existing=state.models.some(m=>m.sourceRival===r.id)||state.projects.some(p=>p.type==='integration'&&p.payload?.rival===r.id);return `<article class="public-base"><div class="public-base-top">${I.brand(r)}<div><h3>${esc(r.name)}</h3><small>${BRANDS[r.brand].name} · ${r.params}</small></div></div><p>${esc(r.note)}</p><div class="help">集成 ${money(r.cost,0)} 万 · ${r.weeks} 周<br>接入后可继续训练、微调或蒸馏。</div>${btn(existing?'已经接入或集成中':'引入这个基座 '+icon('arrow'),'importBase','small primary',`data-id="${r.id}" ${existing?'disabled':''}`)}<a class="source-link" style="margin:10px 0 0" href="${r.url}" target="_blank" rel="noopener noreferrer">查看原始模型资料 ↗</a></article>`;}).join('')}</div><p class="help mt">此操作在游戏内创建适配模型，保留基座来源；不会下载或实际训练现实权重。模型许可和使用范围以原始资料为准。</p></div>`,'inbox-modal');}
function commissionModal(){modal(`${modalHead('委托一份，属于你的材料。','选择主题、材料形态与采集渠道。完成后可与现有材料自由混合。')}<form data-form="commission"><div class="modal-body"><div class="form-grid">${field('材料名称','<input name="name" maxlength="45" placeholder="例如：长篇故事与角色记忆" required>','',true)}${field('材料规模 · B tokens','<input name="tokens" type="number" min="0.1" max="50" step="0.1" value="1">')}${field('材料形态','<select name="format"><option value="text">领域文本与解答</option><option value="dialogue">任务示范与多轮对话</option><option value="preference">回答偏好与纠错</option></select>')}${field('采集渠道','<select name="source"><option value="community">社区贡献与整理 · 成本较低</option><option value="expert">专家编写与复核 · 质量较高</option><option value="teacher">自有模型生成与筛选 · 依赖教师能力</option></select>','不同渠道影响成本、周期和最终材料质量。',true)}${field('采集主题，可同时选择',`<div class="check-chips">${DIM.map((d,i)=>`<label class="check-chip"><input type="checkbox" name="focus" value="${d.id}" ${i===0?'checked':''}>${d.name}</label>`).join('')}</div>`,'多个主题将平均组成材料的初始覆盖方向。',true)}</div><div id="commission-estimate" class="commission-preview">${commissionPreview({tokens:1,source:'community'})}</div><p class="help mt">这是一项并行任务，需要团队和少量算力。采集完成后才会确定抽样质量，不保证每一批材料都同样出色。</p></div><div class="modal-footer">${btn('暂时不采集','close','ghost')}<button class="btn primary" type="submit">安排采集任务</button></div></form>`);}
function commissionPreview(opts){const e=C.collectionEstimate(state,opts);return `<div><strong>${money(e.cost,0)}万</strong><small>本次预算</small></div><div><strong>${e.weeks}周</strong><small>预计周期</small></div><div><strong>${n(e.tokens,1)}B</strong><small>目标规模</small></div>`;}
function promotionsModal(){modal(`${modalHead('让合适的人，先遇见你。','主题活动可以并行开展；服务容量与免费补贴仍由你的经营策略控制。')}<div class="modal-body"><div class="promotion-list">${C.PROMOTIONS.map(p=>{const active=state.trends.some(t=>t.promotion===p.id&&t.until>=state.week);return `<article class="promotion-card"><h3>${p.name}</h3><p>${p.desc}</p><div class="help">${money(p.cost,0)} 万 · ${p.weeks} 周<br>${SEGMENTS.find(g=>g.id===p.group).name} 尝试意愿 +${n(p.effect*100)}%</div>${btn(active?'活动进行中':'开始这场活动','startPromotion','small primary',`data-id="${p.id}" ${active?'disabled':''}`)}</article>`;}).join('')}</div></div>`,'inbox-modal');}
function learnFromDuel(id){const d=state.campaign.duels.find(d=>d.id===id);if(!d)return;const weak=d.groups.slice().sort((a,b)=>a.you-b.you)[0];config=E.defaultConfig(state);config.base=d.model;config.name=d.ownName+' · 下一轮';config.volume=1;config.weights=weak.segment==='dev'?{web:10,dialogue:20,code:55,math:15}:weak.segment==='rp'?{web:10,dialogue:20,roleplay:60,books:10}:weak.segment==='science'?{web:10,dialogue:15,math:60,preference:15}:{web:25,dialogue:50,preference:25};researchTab='builder';close();go('research');toast('已准备一个针对性草案。材料、结构和投入都可继续修改。');}
function animateHQMetrics(before){if(view!=='overview'||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const nodes=[...document.querySelectorAll('.resource strong')],starts=[before.cash,before.users,before.influence,before.projects],ends=[state.cash,E.totalUsers(state),state.influence,state.projects.filter(p=>p.status==='running').length],formats=[v=>n(v,1),v=>compact(Math.round(v)),v=>n(v,1),v=>n(v)];const began=performance.now();const frame=now=>{const t=Math.min(1,(now-began)/650),ease=1-Math.pow(1-t,3);nodes.forEach((el,i)=>{if(el.isConnected&&el.firstChild?.nodeType===3)el.firstChild.nodeValue=formats[i](starts[i]+(ends[i]-starts[i])*ease);});if(t<1)requestAnimationFrame(frame);};requestAnimationFrame(frame);}
function playTone(kind){if(!state.campaign.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const notes=kind==='win'?[440,554.37,659.25]:kind==='reveal'?[220,330,440]:kind==='week'?[261.63,329.63]:[330,440];for(const [i,f]of notes.entries()){const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=f;o.connect(g);g.connect(audioContext.destination);const t=audioContext.currentTime+i*.085;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.027,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+.28);o.start(t);o.stop(t+.3);}}catch{}}
function stopAmbient(){for(const n of ambientNodes){try{n.stop?.();n.disconnect?.();}catch{}}ambientNodes=[];}
function toggleSound(){state.campaign.sound=!state.campaign.sound;if(state.campaign.sound){try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();for(const [i,f]of [55,82.5,110].entries()){const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=f;g.gain.value=.004/(i+1);o.connect(g);g.connect(audioContext.destination);o.start();ambientNodes.push(o,g);}playTone('start');}catch{state.campaign.sound=false;toast('当前浏览器没有启用声音。',true);}}else stopAmbient();save();render();}
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.arena){if(el.dataset.arena==='own')arenaOwn=el.value;else arenaRival=el.value;render();}if(el.closest('[data-form="commission"]')){const f=new FormData(el.closest('form'));const target=$('#commission-estimate');if(target)target.innerHTML=commissionPreview({tokens:f.get('tokens'),source:f.get('source')});}});
document.addEventListener('input',event=>{const el=event.target;if(el.closest('[data-form="commission"]')){const f=new FormData(el.closest('form'));const target=$('#commission-estimate');if(target)target.innerHTML=commissionPreview({tokens:f.get('tokens'),source:f.get('source')});}});

C.ensureCampaign(state);render();if(!state.started)welcome();else {save();toast('欢迎回到公司。总部、同期竞技场和社区机会已经就绪，原有进度已保留。');}
